/* Word-level causal language model using Divide's binary context compression. */
#define DIVIDE_CHAT
#define D 32
#define V 256
#define MAX_PARAMS 32768
#define main retrieval_main
#include "divide.c"
#undef main
#include <ctype.h>
#define WORD 96
#define ROWS 4096
#define SEQ 256
static char vocab[V][WORD];
static int nv=5;
static const char *special[]={"<unk>","<bos>","<user>","<assistant>","<eos>"};
typedef struct {int ids[SEQ],n,answer;} Dialogue;
static Dialogue corpus[ROWS];
static int rows;
static void vocab_init(void){for(int i=0;i<5;i++)strcpy(vocab[i],special[i]);}
static int word_id(const char *w,int grow){for(int i=0;i<nv;i++)if(!strcmp(w,vocab[i]))return i;if(!grow)return 0;if(nv==V)fail("vocabulary exceeds 256; reduce corpus vocabulary");strcpy(vocab[nv],w);return nv++;}
static int tokenize(const char *s,int *ids,int limit,int grow){int n=0;while(*s){while(*s&&isspace((unsigned char)*s))s++;if(!*s)break;char w[WORD];int k=0;if(strchr(".,!?;:",*s))w[k++]=*s++;else while(*s&&!isspace((unsigned char)*s)&&!strchr(".,!?;:",*s)){if(k+1>=WORD)fail("word too long");unsigned char c=(unsigned char)*s++;w[k++]=c<128?(char)tolower(c):(char)c;}w[k]=0;if(n==limit)fail("input too long");ids[n++]=word_id(w,grow);}return n;}
static int read_data(const char *path,Dialogue *data,int grow){FILE *f=fopen(path,"r");if(!f)fail("cannot read dialogue TSV");char line[8192];int r=0;while(fgets(line,sizeof(line),f)){if(!strchr(line,'\n')&&!feof(f))fail("TSV line too long");if(line[0]=='#'||line[0]=='\n')continue;char *tab=strchr(line,'\t');if(!tab)fail("expected question<TAB>answer");*tab++=0;if(r==ROWS)fail("too many dialogues");Dialogue *d=&data[r++];d->ids[0]=1;d->ids[1]=2;d->n=2;d->n+=tokenize(line,d->ids+d->n,SEQ-d->n-2,grow);d->ids[d->n++]=3;d->answer=d->n;d->n+=tokenize(tab,d->ids+d->n,SEQ-d->n-1,grow);d->ids[d->n++]=4;}if(ferror(f)||fclose(f))fail("read failed");if(!r)fail("empty corpus");return r;}
/* Numeric inference: no autodiff nodes, no optimizer, and no training corpus. */
typedef struct {double h[D],score;int start,len;} Memory;
static void project(Model *m,int off,const double *x,double *y,int count){for(int j=0;j<count;j++){double s=0;for(int k=0;k<D;k++)s+=m->p[off+j*D+k]*x[k];y[j]=s;}}
static double salience(Model *m,const double *h){double s=0;for(int j=0;j<D;j++)s+=m->p[m->span+j]*h[j];return s/sqrt(D);}
static void distribution(Model *m,const int *ids,int n,int recent,int dense,double *p,int *slots){
    Memory stack[MAX_CONTEXT],b;double leaves[V][D],x[D],q[D];unsigned char seen[V]={0};int count=0,old=dense?0:n-recent;if(old<0)old=0;
    for(int i=0;i<n;i++){int id=ids[i];if(!seen[id]){project(m,m->merge,m->p+m->emb+id*D,leaves[id],D);for(int j=0;j<D;j++)leaves[id][j]=tanh(leaves[id][j]+m->p[m->bias+j]);seen[id]=1;}b.start=i;b.len=1;for(int j=0;j<D;j++)b.h[j]=leaves[id][j]+(i?leaves[id][j]*leaves[ids[i-1]][(j+1)%D]:0);b.score=salience(m,b.h);
        if(i<old)while(count&&stack[count-1].len==b.len){Memory a=stack[--count];double mx=fmax(a.score,b.score),wa=exp(a.score-mx),wb=exp(b.score-mx),sum=wa+wb;wa/=sum;wb/=sum;for(int j=0;j<D;j++)b.h[j]=sqrt(2.0)*(wa*a.h[j]+wb*b.h[j]);b.score=sqrt(2.0)*(wa*a.score+wb*b.score);b.start=a.start;b.len+=a.len;}stack[count++]=b;
    }
    for(int j=0;j<D;j++)x[j]=.5*(leaves[ids[n-2]][j]+leaves[ids[n-1]][j]);project(m,m->q,x,q,D);
    double scores[MAX_CONTEXT],values[MAX_CONTEXT][D],mx=-1e300;
    for(int i=0;i<count;i++){double key[D];for(int j=0;j<D;j++)x[j]=stack[i].h[j]+m->p[m->pos+j]*(double)stack[i].start/n+m->p[m->span+j]*log2(1.0+stack[i].len)/10;project(m,m->k,x,key,D);project(m,m->val,x,values[i],D);scores[i]=0;for(int j=0;j<D;j++)scores[i]+=q[j]*key[j];scores[i]/=sqrt(D);if(scores[i]>mx)mx=scores[i];}
    double sum=0;for(int i=0;i<count;i++){scores[i]=exp(scores[i]-mx);sum+=scores[i];}for(int j=0;j<D;j++){double s=0;for(int i=0;i<count;i++)s+=scores[i]*values[i][j]/sum;x[j]=tanh(s+q[j]);}project(m,m->out,x,p,V);for(int i=0;i<V;i++)p[i]+=m->p[m->ob+i];*slots=count;
}
static double probability(double *logits,int target){double mx=logits[0],sum=0;for(int i=1;i<V;i++)if(logits[i]>mx)mx=logits[i];for(int i=0;i<V;i++)sum+=exp(logits[i]-mx);return exp(logits[target]-mx)/sum;}
static void save_chat(Model *m,const char *path,int context,int recent,int dense){FILE *f=fopen(path,"w");if(!f)fail("cannot write chat checkpoint");fprintf(f,"DIVIDECHAT1 %d %d %d %d %d %d %d\n",D,V,m->count,nv,context,recent,dense);for(int i=0;i<nv;i++)fprintf(f,"%s\n",vocab[i]);for(int i=0;i<m->count;i++)fprintf(f,"%.17g\n",m->p[i]);if(fclose(f))fail("checkpoint write failed");}
static void load_chat(Model *m,const char *path,int *context,int *recent,int *dense){FILE *f=fopen(path,"r");if(!f)fail("cannot read chat checkpoint");char magic[32];int d,v,count;if(fscanf(f,"%31s%d%d%d%d%d%d%d",magic,&d,&v,&count,&nv,context,recent,dense)!=8||strcmp(magic,"DIVIDECHAT1")||d!=D||v!=V||count!=m->count||nv<5||nv>V||*context<8||*context>MAX_CONTEXT||*recent<1||*recent>*context||(*dense!=0&&*dense!=1))fail("invalid chat checkpoint");for(int i=0;i<nv;i++)if(fscanf(f,"%95s",vocab[i])!=1)fail("invalid vocabulary");for(int i=0;i<5;i++)if(strcmp(vocab[i],special[i]))fail("invalid special tokens");for(int i=0;i<count;i++)if(fscanf(f,"%lf",&m->p[i])!=1||!isfinite(m->p[i]))fail("invalid weights");fclose(f);}
static void evaluate(Model *m,Dialogue *data,int size,int context,int recent,int dense,const char *label){double nll=0,start=now();int correct=0,total=0,slots=0;double p[V];for(int r=0;r<size;r++)for(int at=data[r].answer;at<data[r].n;at++){int begin=at>context?at-context:0;distribution(m,data[r].ids+begin,at-begin,recent,dense,p,&slots);int best=0;for(int j=1;j<V;j++)if(p[j]>p[best])best=j;correct+=best==data[r].ids[at];nll-=log(fmax(1e-300,probability(p,data[r].ids[at])));total++;}printf("%s tokens=%d nll=%.4f next_token_accuracy=%.2f%% ms/token=%.4f\n",label,total,nll/total,100.0*correct/total,1000*(now()-start)/total);}
static void emit_word(int id,int first){if(!first&& !strchr(".,!?;:",vocab[id][0]))putchar(' ');fputs(vocab[id],stdout);fflush(stdout);}
static int generate(Model *m,int *history,int *used,int context,int recent,int dense,int maxnew,double temp){double p[V];int made=0;for(;made<maxnew;made++){int slots;distribution(m,history,*used,recent,dense,p,&slots);int best=4;for(int j=5;j<nv;j++)if(p[j]>p[best])best=j;int id=best;if(temp>0){double mx=p[best],sum=0;for(int j=4;j<nv;j++){p[j]=exp((p[j]-mx)/temp);sum+=p[j];}double draw=uniform()*sum;id=nv-1;for(int j=4;j<nv;j++){draw-=p[j];if(draw<=0){id=j;break;}}}if(*used==context){memmove(history,history+1,(size_t)(context-1)*sizeof(int));(*used)--;}history[(*used)++]=id;if(id==4)break;emit_word(id,made==0);}putchar('\n');return made;}
static void append(int *h,int *n,int id,int context){if(*n==context){memmove(h,h+1,(size_t)(context-1)*sizeof(int));(*n)--;}h[(*n)++]=id;}
int main(int argc,char **argv){const char *train=NULL,*eval=NULL,*load=NULL,*savepath="chat/basic.weights",*prompt=NULL;int steps=100000,context=64,recent=8,seed=42,maxnew=32,dense=0,interactive=0,selftest=0;double temp=0,lr=.003;
    for(int i=1;i<argc;i++){const char *opt=argv[i];if(!strcmp(opt,"--help")){puts("Divide Chat: small word-level Turkish language model\n--train FILE --save FILE --steps N --context N --recent N --seed N --dense\n--load FILE --prompt TEXT | --chat [--temperature 0..2 --max-new N]\n--eval FILE --self-test\nTraining/evaluation TSV: question<TAB>answer. Chat: /reset, /quit.");return 0;}if(!strcmp(opt,"--chat")){interactive=1;continue;}if(!strcmp(opt,"--dense")){dense=1;continue;}if(!strcmp(opt,"--self-test")){selftest=1;continue;}if(i+1>=argc)fail("missing option value");const char *value=argv[++i];if(!strcmp(opt,"--train"))train=value;else if(!strcmp(opt,"--eval"))eval=value;else if(!strcmp(opt,"--load"))load=value;else if(!strcmp(opt,"--save"))savepath=value;else if(!strcmp(opt,"--prompt"))prompt=value;else if(!strcmp(opt,"--steps"))steps=number(value);else if(!strcmp(opt,"--context"))context=number(value);else if(!strcmp(opt,"--recent"))recent=number(value);else if(!strcmp(opt,"--seed"))seed=number(value);else if(!strcmp(opt,"--max-new"))maxnew=number(value);else if(!strcmp(opt,"--temperature")){char *end;temp=strtod(value,&end);if(*end||!isfinite(temp)||temp<0||temp>2)fail("invalid temperature");}else fail("unknown option");}
    if(context<8||context>MAX_CONTEXT||recent>context||steps>10000000||maxnew>256)fail("invalid model limits");Model *m=calloc(1,sizeof(*m));if(!m)fail("out of memory");init(m,(uint64_t)seed);vocab_init();compressor=7;gated_readout=0;binding_kind=0;score_cache=1;
    if(load)load_chat(m,load,&context,&recent,&dense);rng=(uint64_t)seed;
    if(selftest){int ids[]={1,2,5,6,7,8,5,6,7,8,5,6,3};double p[V];int slots,pred,blocks;int loss=forward(m,ids,13,3,1,5,&pred,&blocks);double reference=t.n[loss].v;distribution(m,ids,13,3,0,p,&slots);if(fabs(reference+log(probability(p,5)))>1e-10||slots!=blocks)fail("numeric/autodiff mismatch");int check[]={m->emb+5*D,m->merge+1,m->q+3,m->span+2,m->out+5*D,m->pos};backward(loss);double grads[6];for(int i=0;i<6;i++)grads[i]=t.n[check[i]].g;for(int i=0;i<6;i++){int k=check[i];double orig=m->p[k],eps=1e-5;m->p[k]=orig+eps;int l=forward(m,ids,13,3,1,5,&pred,&blocks);double a=t.n[l].v;m->p[k]=orig-eps;l=forward(m,ids,13,3,1,5,&pred,&blocks);double b=t.n[l].v;m->p[k]=orig;if(fabs((a-b)/(2*eps)-grads[i])>1e-5)fail("chat gradient mismatch");}puts("chat numeric inference and finite-difference gradients passed");free(t.n);free(m);return 0;}
    if(train){rows=read_data(train,corpus,1);printf("training dialogues=%d vocabulary=%d parameters=%d context=%d recent=%d mode=%s\n",rows,nv,m->count,context,recent,dense?"dense":"divide");double start=now(),running=0;for(int step=0;step<steps;step++){Dialogue *d=&corpus[random32()%(unsigned)rows];int at=d->answer+(int)(random32()%(unsigned)(d->n-d->answer));int begin=at>context?at-context:0,pred,blocks;int loss=forward(m,d->ids+begin,at-begin,recent,!dense,d->ids[at],&pred,&blocks);running+=t.n[loss].v;backward(loss);update(m,lr*(.2+.8*.5*(1+cos(3.141592653589793*step/steps))));if((step+1)%5000==0){fprintf(stderr,"step=%d nll=%.4f elapsed=%.1fs\n",step+1,running/5000,now()-start);running=0;}}save_chat(m,savepath,context,recent,dense);printf("saved=%s train_seconds=%.3f\n",savepath,now()-start);evaluate(m,corpus,rows,context,recent,dense,"training-set");}
    if(eval){static Dialogue validation[ROWS];int size=read_data(eval,validation,0);evaluate(m,validation,size,context,recent,dense,"evaluation");}
    if(prompt||interactive){if(!load&&!train)fail("chat requires --load or --train");int history[MAX_CONTEXT],used=1;history[0]=1;char line[8192];do{const char *input=prompt;if(interactive){fputs("you> ",stdout);fflush(stdout);if(!fgets(line,sizeof(line),stdin))break;line[strcspn(line,"\r\n")]=0;if(!strcmp(line,"/quit"))break;if(!strcmp(line,"/reset")){used=1;history[0]=1;puts("history cleared");continue;}input=line;}int ids[SEQ];int n=tokenize(input,ids,SEQ,0),unknown=0;for(int i=0;i<n;i++)unknown+=ids[i]==0;if(unknown)fprintf(stderr,"note: %d unknown word(s); this vocabulary is small\n",unknown);append(history,&used,2,context);for(int i=0;i<n;i++)append(history,&used,ids[i],context);append(history,&used,3,context);if(interactive)fputs("divide> ",stdout);generate(m,history,&used,context,recent,dense,maxnew,temp);if(history[used-1]!=4)append(history,&used,4,context);}while(interactive);}
    if(!train&&!load&&!selftest)fail("use --train or --load; see --help");free(t.n);free(m);return 0;
}
